values (
  'en-mental-math-trivia',
  'Mental Math Trivia: Fast Calculation Tricks',
  'Eight questions on doubling, percentages, squares and the clever shortcuts that make everyday arithmetic faster.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"What is 15% of 200?","options":[{"id":"a","text":"15","is_correct":false},{"id":"b","text":"20","is_correct":false},{"id":"c","text":"30","is_correct":true},{"id":"d","text":"45","is_correct":false}],"explanation":"10% of 200 is 20 and 5% is 10, so 15% is 20 + 10 = 30."},{"id":"q2","question":"What is 17 × 6?","options":[{"id":"a","text":"92","is_correct":false},{"id":"b","text":"96","is_correct":false},{"id":"c","text":"102","is_correct":true},{"id":"d","text":"112","is_correct":false}],"explanation":"Split it: 10 × 6 = 60 and 7 × 6 = 42, so 60 + 42 = 102."},{"id":"q3","question":"What is 12 squared?","options":[{"id":"a","text":"124","is_correct":false},{"id":"b","text":"144","is_correct":true},{"id":"c","text":"128","is_correct":false},{"id":"d","text":"164","is_correct":false}],"explanation":"12 × 12 = 144, one of the most useful squares to memorize."},{"id":"q4","question":"A whole number is divisible by 3 if...","options":[{"id":"a","text":"it ends in a 3","is_correct":false},{"id":"b","text":"it ends in an even digit","is_correct":false},{"id":"c","text":"it ends in a 6","is_correct":false},{"id":"d","text":"the sum of its digits is divisible by 3","is_correct":true}],"explanation":"123 works because 1 + 2 + 3 = 6, and 6 is divisible by 3."},{"id":"q5","question":"Using the doubling trick (25 × 16 = 50 × 8), what is 25 × 16?","options":[{"id":"a","text":"350","is_correct":false},{"id":"b","text":"400","is_correct":true},{"id":"c","text":"425","is_correct":false},{"id":"d","text":"450","is_correct":false}],"explanation":"Doubling 25 to 50 halves 16 to 8, and 50 × 8 = 400."},{"id":"q6","question":"What is 99 + 99 + 99?","options":[{"id":"a","text":"277","is_correct":false},{"id":"b","text":"287","is_correct":false},{"id":"c","text":"297","is_correct":true},{"id":"d","text":"307","is_correct":false}],"explanation":"3 × 99 = 3 × 100 − 3 = 300 − 3 = 297."},{"id":"q7","question":"In the expression 4 + 3 × 2, which operation does the order of operations say to do first?","options":[{"id":"a","text":"The addition, working left to right","is_correct":false},{"id":"b","text":"The multiplication","is_correct":true},{"id":"c","text":"Whichever uses the largest number","is_correct":false},{"id":"d","text":"Either one; the result is the same","is_correct":false}],"explanation":"Multiplication comes before addition: 4 + 6 = 10, not 14."},{"id":"q8","question":"What is the fraction 1/4 as a percentage?","options":[{"id":"a","text":"15%","is_correct":false},{"id":"b","text":"20%","is_correct":false},{"id":"c","text":"40%","is_correct":false},{"id":"d","text":"25%","is_correct":true}],"explanation":"1/4 = 0.25, and multiplying by 100 gives 25%."}]'::jsonb,
  null,
  array['math', 'trivia', 'mental math', 'arithmetic', 'numbers']::text[],
  3,
  'published',
  false,
  false,
  now()
)
