values (
  'es-trivia-calculo-mental',
  'Trivia de cálculo mental: trucos para calcular rápido',
  'Ocho preguntas sobre doblar, porcentajes, cuadrados y los atajos que hacen más rápida la aritmética de cada día.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"¿Cuánto es el 15 % de 200?","options":[{"id":"a","text":"15","is_correct":false},{"id":"b","text":"20","is_correct":false},{"id":"c","text":"30","is_correct":true},{"id":"d","text":"45","is_correct":false}],"explanation":"El 10 % de 200 es 20 y el 5 % es 10, así que el 15 % es 20 + 10 = 30."},{"id":"q2","question":"¿Cuánto es 17 × 6?","options":[{"id":"a","text":"92","is_correct":false},{"id":"b","text":"96","is_correct":false},{"id":"c","text":"102","is_correct":true},{"id":"d","text":"112","is_correct":false}],"explanation":"Se descompone: 10 × 6 = 60 y 7 × 6 = 42, así que 60 + 42 = 102."},{"id":"q3","question":"¿Cuánto es 12 al cuadrado?","options":[{"id":"a","text":"124","is_correct":false},{"id":"b","text":"144","is_correct":true},{"id":"c","text":"128","is_correct":false},{"id":"d","text":"164","is_correct":false}],"explanation":"12 × 12 = 144, uno de los cuadrados más útiles de memorizar."},{"id":"q4","question":"Un número entero es divisible por 3 si...","options":[{"id":"a","text":"termina en 3","is_correct":false},{"id":"b","text":"termina en un dígito par","is_correct":false},{"id":"c","text":"termina en 6","is_correct":false},{"id":"d","text":"la suma de sus dígitos es divisible por 3","is_correct":true}],"explanation":"El 123 funciona porque 1 + 2 + 3 = 6, y 6 es divisible por 3."},{"id":"q5","question":"Con el truco de doblar (25 × 16 = 50 × 8), ¿cuánto es 25 × 16?","options":[{"id":"a","text":"350","is_correct":false},{"id":"b","text":"400","is_correct":true},{"id":"c","text":"425","is_correct":false},{"id":"d","text":"450","is_correct":false}],"explanation":"Al doblar 25 a 50, el 16 baja a 8, y 50 × 8 = 400."},{"id":"q6","question":"¿Cuánto es 99 + 99 + 99?","options":[{"id":"a","text":"277","is_correct":false},{"id":"b","text":"287","is_correct":false},{"id":"c","text":"297","is_correct":true},{"id":"d","text":"307","is_correct":false}],"explanation":"3 × 99 = 3 × 100 − 3 = 300 − 3 = 297."},{"id":"q7","question":"En la expresión 4 + 3 × 2, ¿qué operación indica el orden de las operaciones que se hace primero?","options":[{"id":"a","text":"La suma, de izquierda a derecha","is_correct":false},{"id":"b","text":"La multiplicación","is_correct":true},{"id":"c","text":"La que usa el número más grande","is_correct":false},{"id":"d","text":"Cualquiera; el resultado es el mismo","is_correct":false}],"explanation":"La multiplicación va antes que la suma: 4 + 6 = 10, no 14."},{"id":"q8","question":"¿A qué porcentaje equivale la fracción 1/4?","options":[{"id":"a","text":"15 %","is_correct":false},{"id":"b","text":"20 %","is_correct":false},{"id":"c","text":"40 %","is_correct":false},{"id":"d","text":"25 %","is_correct":true}],"explanation":"1/4 = 0,25, y al multiplicar por 100 da el 25 %."}]'::jsonb,
  null,
  array['matemáticas', 'trivia', 'cálculo mental', 'aritmética', 'números']::text[],
  3,
  'published',
  false,
  false,
  now()
)
