insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-logic-puzzles-trivia',
  'Logic Puzzles Trivia: Riddles and Deduction',
  'Eight questions on classic logic riddles, from knights and knaves to river crossings and sneaky paradoxes.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"On an island where knights always tell the truth and knaves always lie, an inhabitant says ''I am a knave.'' What is going on?","options":[{"id":"a","text":"He is a knight","is_correct":false},{"id":"b","text":"He is a knave","is_correct":false},{"id":"c","text":"He could be either","is_correct":false},{"id":"d","text":"No inhabitant could say that","is_correct":true}],"explanation":"A knight saying it would be lying, and a knave saying it would be telling the truth: a paradox."},{"id":"q2","question":"A farmer must carry a wolf, a goat and a cabbage across a river one at a time, and the wolf eats the goat while the goat eats the cabbage. What does he take across first?","options":[{"id":"a","text":"The wolf","is_correct":false},{"id":"b","text":"The goat","is_correct":true},{"id":"c","text":"The cabbage","is_correct":false},{"id":"d","text":"Any of them works","is_correct":false}],"explanation":"He takes the goat first (wolf and cabbage are safe together), then crosses with the wolf, returns with the goat, leaves it to take the cabbage over, and finally goes back for the goat."},{"id":"q3","question":"Three boxes are labeled ''apples'', ''oranges'' and ''apples and oranges'', but every label is wrong. You may draw one fruit from one box. Which box do you pick from?","options":[{"id":"a","text":"The one labeled ''apples''","is_correct":false},{"id":"b","text":"The one labeled ''oranges''","is_correct":false},{"id":"c","text":"The one labeled ''apples and oranges''","is_correct":true},{"id":"d","text":"It makes no difference","is_correct":false}],"explanation":"Since the mixed label is also wrong, that box holds only one fruit, and the draw reveals all three boxes."},{"id":"q4","question":"If all bloops are razzies and all razzies are lazzies, then all bloops are...","options":[{"id":"a","text":"Definitely lazzies","is_correct":true},{"id":"b","text":"Probably lazzies","is_correct":false},{"id":"c","text":"Never lazzies","is_correct":false},{"id":"d","text":"Impossible to know","is_correct":false}],"explanation":"A classic syllogism: membership passes through the chain from bloops to razzies to lazzies."},{"id":"q5","question":"A bat and a ball cost $1.10 in total, and the bat costs $1.00 more than the ball. How much does the ball cost?","options":[{"id":"a","text":"10 cents","is_correct":false},{"id":"b","text":"5 cents","is_correct":true},{"id":"c","text":"1 cent","is_correct":false},{"id":"d","text":"15 cents","is_correct":false}],"explanation":"If the ball costs 5 cents, the bat costs $1.05, and $1.05 + $0.05 = $1.10."},{"id":"q6","question":"Two fathers and two sons go fishing. Each catches one fish and they bring home three fish in total. How is that possible?","options":[{"id":"a","text":"They shared one fish","is_correct":false},{"id":"b","text":"One of them lied","is_correct":false},{"id":"c","text":"They are a grandfather, a father and a son","is_correct":true},{"id":"d","text":"One caught two fish","is_correct":false}],"explanation":"Three people cover the roles: the father is both a son and a father."},{"id":"q7","question":"Two doors hide safety and doom, guarded by one truth-teller and one liar. Which single question finds the safe door?","options":[{"id":"a","text":"Ask a guard if he is the liar","is_correct":false},{"id":"b","text":"Ask a guard which door is safe","is_correct":false},{"id":"c","text":"Ask a guard which door the other guard would call safe, then pick the opposite","is_correct":true},{"id":"d","text":"Ask a guard if two plus two is four","is_correct":false}],"explanation":"The liar and the truth-teller both point to the doomed door, so choosing the other door always works."},{"id":"q8","question":"A man looks at a portrait and says: ''Brothers and sisters I have none, but that man''s father is my father''s son.'' Who is in the portrait?","options":[{"id":"a","text":"The man himself","is_correct":false},{"id":"b","text":"His father","is_correct":false},{"id":"c","text":"His nephew","is_correct":false},{"id":"d","text":"His son","is_correct":true}],"explanation":"With no siblings, ''my father''s son'' is himself, so the portrait shows his own son."}]'::jsonb,
  null,
  array['logic', 'trivia', 'puzzles', 'riddles', 'reasoning']::text[],
  3,
  'published',
  false,
  false,
  now()
)
