insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-logica',
  'Trivia de lógica: acertijos y deducción',
  'Ocho preguntas sobre acertijos de lógica clásicos, de caballeros y mentirosos a cruces de río y paradojas.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"En una isla donde los caballeros siempre dicen la verdad y los mentirosos siempre mienten, un habitante dice «soy mentiroso». ¿Qué ocurre?","options":[{"id":"a","text":"Es un caballero","is_correct":false},{"id":"b","text":"Es un mentiroso","is_correct":false},{"id":"c","text":"Podría ser cualquiera","is_correct":false},{"id":"d","text":"Ningún habitante podría decir eso","is_correct":true}],"explanation":"Un caballero que lo dice estaría mintiendo y un mentiroso estaría diciendo la verdad: es una paradoja."},{"id":"q2","question":"Un granjero debe cruzar un río con un lobo, una cabra y una col de a uno por vez, sabiendo que el lobo se come a la cabra y la cabra se come la col. ¿Qué lleva primero?","options":[{"id":"a","text":"El lobo","is_correct":false},{"id":"b","text":"La cabra","is_correct":true},{"id":"c","text":"La col","is_correct":false},{"id":"d","text":"Cualquiera sirve","is_correct":false}],"explanation":"Primero cruza la cabra (el lobo y la col quedan seguros juntos), luego cruza el lobo, regresa con la cabra, la deja para cruzar la col, y al final vuelve por la cabra."},{"id":"q3","question":"Tres cajas dicen «manzanas», «naranjas» y «manzanas y naranjas», pero todas las etiquetas están mal. Puedes sacar una fruta de una sola caja. ¿De cuál?","options":[{"id":"a","text":"La que dice «manzanas»","is_correct":false},{"id":"b","text":"La que dice «naranjas»","is_correct":false},{"id":"c","text":"La que dice «manzanas y naranjas»","is_correct":true},{"id":"d","text":"Da igual cuál","is_correct":false}],"explanation":"Como la etiqueta mixta también está mal, esa caja tiene una sola fruta y lo que saques revela las tres."},{"id":"q4","question":"Si todos los bloops son razzies y todos los razzies son lazzies, entonces todos los bloops son...","options":[{"id":"a","text":"Definitivamente lazzies","is_correct":true},{"id":"b","text":"Probablemente lazzies","is_correct":false},{"id":"c","text":"Nunca lazzies","is_correct":false},{"id":"d","text":"Imposible de saber","is_correct":false}],"explanation":"Un silogismo clásico: la pertenencia pasa en cadena de bloops a razzies y de razzies a lazzies."},{"id":"q5","question":"Un bate y una pelota cuestan 1,10 dólares en total, y el bate cuesta 1 dólar más que la pelota. ¿Cuánto cuesta la pelota?","options":[{"id":"a","text":"10 centavos","is_correct":false},{"id":"b","text":"5 centavos","is_correct":true},{"id":"c","text":"1 centavo","is_correct":false},{"id":"d","text":"15 centavos","is_correct":false}],"explanation":"Si la pelota cuesta 5 centavos, el bate cuesta 1,05 dólares, y 1,05 + 0,05 = 1,10."},{"id":"q6","question":"Dos padres y dos hijos van a pescar. Cada uno pesca un pez y vuelven con tres peces en total. ¿Cómo es posible?","options":[{"id":"a","text":"Compartieron un pez","is_correct":false},{"id":"b","text":"Uno de ellos mintió","is_correct":false},{"id":"c","text":"Son un abuelo, un padre y un hijo","is_correct":true},{"id":"d","text":"Uno pescó dos peces","is_correct":false}],"explanation":"Tres personas cubren los roles: el padre es a la vez hijo y padre."},{"id":"q7","question":"Dos puertas esconden la salvación y la perdición, custodiadas por un guardia que dice la verdad y otro que miente. ¿Qué única pregunta revela la puerta segura?","options":[{"id":"a","text":"Preguntar a un guardia si es el mentiroso","is_correct":false},{"id":"b","text":"Preguntar a un guardia cuál puerta es segura","is_correct":false},{"id":"c","text":"Preguntar a un guardia qué puerta diría el otro y elegir la contraria","is_correct":true},{"id":"d","text":"Preguntar a un guardia si dos más dos son cuatro","is_correct":false}],"explanation":"El mentiroso y el sincero señalan la puerta mala, así que elegir la otra siempre funciona."},{"id":"q8","question":"Un hombre mira un retrato y dice: «Hermanos y hermanas no tengo, pero el padre de ese hombre es el hijo de mi padre». ¿Quién está en el retrato?","options":[{"id":"a","text":"El propio hombre","is_correct":false},{"id":"b","text":"Su padre","is_correct":false},{"id":"c","text":"Su sobrino","is_correct":false},{"id":"d","text":"Su hijo","is_correct":true}],"explanation":"Sin hermanos, «el hijo de mi padre» es él mismo, así que el retrato muestra a su hijo."}]'::jsonb,
  null,
  array['lógica', 'trivia', 'acertijos', 'enigmas', 'razonamiento']::text[],
  3,
  'published',
  false,
  false,
  now()
)
