insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-math-history-trivia',
  'Math History Trivia: From Euclid to Euler',
  'Eight questions on the people and ideas that shaped mathematics, from ancient geometry to the birth of computing.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"Which ancient Greek mathematician wrote ''Elements'', the geometry textbook used for over 2,000 years?","options":[{"id":"a","text":"Pythagoras","is_correct":false},{"id":"b","text":"Euclid","is_correct":true},{"id":"c","text":"Archimedes","is_correct":false},{"id":"d","text":"Thales","is_correct":false}],"explanation":"Euclid compiled ''Elements'' in Alexandria around 300 BCE, and it stayed in classrooms for millennia."},{"id":"q2","question":"The Pythagorean theorem, a² + b² = c², relates the sides of which figure?","options":[{"id":"a","text":"A right triangle","is_correct":true},{"id":"b","text":"A circle","is_correct":false},{"id":"c","text":"A rectangle","is_correct":false},{"id":"d","text":"Any triangle","is_correct":false}],"explanation":"The theorem links the two legs of a right triangle to its hypotenuse."},{"id":"q3","question":"Which mathematician allegedly shouted ''Eureka!'' after grasping the principle of buoyancy in his bath?","options":[{"id":"a","text":"Euclid","is_correct":false},{"id":"b","text":"Pythagoras","is_correct":false},{"id":"c","text":"Archimedes","is_correct":true},{"id":"d","text":"Aristotle","is_correct":false}],"explanation":"The story says Archimedes ran through Syracuse shouting ''Eureka!'' (''I found it'')."},{"id":"q4","question":"Where was zero first treated as a number in its own right, with rules for arithmetic?","options":[{"id":"a","text":"Egypt","is_correct":false},{"id":"b","text":"Greece","is_correct":false},{"id":"c","text":"China","is_correct":false},{"id":"d","text":"India","is_correct":true}],"explanation":"Indian mathematicians such as Brahmagupta gave rules for zero in the 7th century."},{"id":"q5","question":"Which sequence, where each term is the sum of the two before it (1, 1, 2, 3, 5, 8...), is named after a medieval Italian mathematician?","options":[{"id":"a","text":"The Pascal sequence","is_correct":false},{"id":"b","text":"The Fibonacci sequence","is_correct":true},{"id":"c","text":"The Euclid sequence","is_correct":false},{"id":"d","text":"The Gauss sequence","is_correct":false}],"explanation":"Fibonacci introduced the sequence to Europe in 1202 in his book Liber Abaci."},{"id":"q6","question":"Euler''s identity, e^(iπ) + 1 = 0, connects how many fundamental constants of mathematics?","options":[{"id":"a","text":"Three","is_correct":false},{"id":"b","text":"Four","is_correct":false},{"id":"c","text":"Five","is_correct":true},{"id":"d","text":"Six","is_correct":false}],"explanation":"It links e, i, π, 1 and 0 in a single equation."},{"id":"q7","question":"Who is often called the first computer programmer, thanks to her notes on Babbage''s Analytical Engine?","options":[{"id":"a","text":"Ada Lovelace","is_correct":true},{"id":"b","text":"Marie Curie","is_correct":false},{"id":"c","text":"Charles Babbage","is_correct":false},{"id":"d","text":"Alan Turing","is_correct":false}],"explanation":"Lovelace''s 1843 notes included an algorithm for the machine that was never built."},{"id":"q8","question":"Which two mathematicians developed calculus independently in the 17th century, sparking a famous priority dispute?","options":[{"id":"a","text":"Descartes and Fermat","is_correct":false},{"id":"b","text":"Euler and Lagrange","is_correct":false},{"id":"c","text":"Gauss and Riemann","is_correct":false},{"id":"d","text":"Newton and Leibniz","is_correct":true}],"explanation":"Newton and Leibniz reached calculus separately, and their followers argued over priority for decades."}]'::jsonb,
  null,
  array['math', 'trivia', 'history', 'mathematicians', 'science']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-historia-de-las-matematicas',
  'Trivia de historia de las matemáticas: de Euclides a Euler',
  'Ocho preguntas sobre las personas y las ideas que dieron forma a las matemáticas, de la geometría antigua al nacimiento de la computación.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"¿Qué matemático griego escribió «Elementos», el manual de geometría que se usó durante más de 2000 años?","options":[{"id":"a","text":"Pitágoras","is_correct":false},{"id":"b","text":"Euclides","is_correct":true},{"id":"c","text":"Arquímedes","is_correct":false},{"id":"d","text":"Tales","is_correct":false}],"explanation":"Euclides compiló «Elementos» en Alejandría hacia el año 300 a. C., y siguió en las aulas por milenios."},{"id":"q2","question":"El teorema de Pitágoras, a² + b² = c², relaciona los lados de qué figura?","options":[{"id":"a","text":"Un triángulo rectángulo","is_correct":true},{"id":"b","text":"Un círculo","is_correct":false},{"id":"c","text":"Un rectángulo","is_correct":false},{"id":"d","text":"Cualquier triángulo","is_correct":false}],"explanation":"El teorema une los dos catetos de un triángulo rectángulo con su hipotenusa."},{"id":"q3","question":"¿Qué matemático, según la leyenda, gritó «¡Eureka!» al comprender el principio de la flotación en la bañera?","options":[{"id":"a","text":"Euclides","is_correct":false},{"id":"b","text":"Pitágoras","is_correct":false},{"id":"c","text":"Arquímedes","is_correct":true},{"id":"d","text":"Aristóteles","is_correct":false}],"explanation":"La historia cuenta que Arquímedes corrió por Siracusa gritando «¡Eureka!» («lo encontré»)."},{"id":"q4","question":"¿Dónde se trató primero al cero como un número con reglas propias para operar?","options":[{"id":"a","text":"En Egipto","is_correct":false},{"id":"b","text":"En Grecia","is_correct":false},{"id":"c","text":"En China","is_correct":false},{"id":"d","text":"En la India","is_correct":true}],"explanation":"Matemáticos indios como Brahmagupta dieron reglas para el cero en el siglo VII."},{"id":"q5","question":"¿Qué sucesión, donde cada término es la suma de los dos anteriores (1, 1, 2, 3, 5, 8...), lleva el nombre de un matemático italiano medieval?","options":[{"id":"a","text":"La sucesión de Pascal","is_correct":false},{"id":"b","text":"La sucesión de Fibonacci","is_correct":true},{"id":"c","text":"La sucesión de Euclides","is_correct":false},{"id":"d","text":"La sucesión de Gauss","is_correct":false}],"explanation":"Fibonacci presentó la sucesión en Europa en 1202, en su libro Liber Abaci."},{"id":"q6","question":"La identidad de Euler, e^(iπ) + 1 = 0, conecta cuántas constantes fundamentales de las matemáticas?","options":[{"id":"a","text":"Tres","is_correct":false},{"id":"b","text":"Cuatro","is_correct":false},{"id":"c","text":"Cinco","is_correct":true},{"id":"d","text":"Seis","is_correct":false}],"explanation":"Une e, i, π, 1 y 0 en una sola ecuación."},{"id":"q7","question":"¿Quién es considerada la primera programadora de la historia, por sus notas sobre la Máquina Analítica de Babbage?","options":[{"id":"a","text":"Ada Lovelace","is_correct":true},{"id":"b","text":"Marie Curie","is_correct":false},{"id":"c","text":"Charles Babbage","is_correct":false},{"id":"d","text":"Alan Turing","is_correct":false}],"explanation":"Las notas de Lovelace de 1843 incluían un algoritmo para una máquina que nunca se construyó."},{"id":"q8","question":"¿Qué dos matemáticos desarrollaron el cálculo por separado en el siglo XVII, lo que desató una famosa disputa por la prioridad?","options":[{"id":"a","text":"Descartes y Fermat","is_correct":false},{"id":"b","text":"Euler y Lagrange","is_correct":false},{"id":"c","text":"Gauss y Riemann","is_correct":false},{"id":"d","text":"Newton y Leibniz","is_correct":true}],"explanation":"Newton y Leibniz llegaron al cálculo por caminos separados, y sus seguidores discutieron la prioridad por décadas."}]'::jsonb,
  null,
  array['matemáticas', 'trivia', 'historia', 'matemáticos', 'ciencia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-probability-trivia',
  'Probability Trivia: Chance, Odds and Paradoxes',
  'Eight questions on coins, dice, cards and the counterintuitive results that make probability so surprising.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"What is the probability of getting heads on a fair coin toss?","options":[{"id":"a","text":"1/4","is_correct":false},{"id":"b","text":"1/2","is_correct":true},{"id":"c","text":"1/3","is_correct":false},{"id":"d","text":"1","is_correct":false}],"explanation":"A fair coin has two equally likely outcomes, so each gets 1/2 or 50%."},{"id":"q2","question":"When rolling one fair six-sided die, what is the probability of rolling a 6?","options":[{"id":"a","text":"1/3","is_correct":false},{"id":"b","text":"1/2","is_correct":false},{"id":"c","text":"1/6","is_correct":true},{"id":"d","text":"1/12","is_correct":false}],"explanation":"One favorable face out of six gives 1/6, about 16.7%."},{"id":"q3","question":"When rolling two dice, which total is the most likely?","options":[{"id":"a","text":"2","is_correct":false},{"id":"b","text":"6","is_correct":false},{"id":"c","text":"12","is_correct":false},{"id":"d","text":"7","is_correct":true}],"explanation":"Seven can be made in six ways (1-6, 2-5, 3-4, 4-3, 5-2, 6-1), more than any other total."},{"id":"q4","question":"In the famous birthday paradox, how many people must be in a room for a greater than 50% chance that two share a birthday?","options":[{"id":"a","text":"23","is_correct":true},{"id":"b","text":"50","is_correct":false},{"id":"c","text":"100","is_correct":false},{"id":"d","text":"183","is_correct":false}],"explanation":"With just 23 people the chance of a shared birthday already passes 50%."},{"id":"q5","question":"In the Monty Hall problem, after the host reveals a goat, switching your door changes your winning chance to...","options":[{"id":"a","text":"1/3, the same as before","is_correct":false},{"id":"b","text":"2/3, double the original","is_correct":true},{"id":"c","text":"1/2, a coin flip","is_correct":false},{"id":"d","text":"1/4, lower than before","is_correct":false}],"explanation":"Your first pick had a 1/3 chance; the other unopened door keeps the remaining 2/3."},{"id":"q6","question":"What is the probability of getting heads twice in a row with a fair coin?","options":[{"id":"a","text":"1/2","is_correct":false},{"id":"b","text":"1/3","is_correct":false},{"id":"c","text":"1/8","is_correct":false},{"id":"d","text":"1/4","is_correct":true}],"explanation":"Independent events multiply: 1/2 × 1/2 = 1/4."},{"id":"q7","question":"Drawing one card from a standard 52-card deck, what is the probability of getting an ace?","options":[{"id":"a","text":"1/13","is_correct":true},{"id":"b","text":"1/26","is_correct":false},{"id":"c","text":"1/4","is_correct":false},{"id":"d","text":"1/52","is_correct":false}],"explanation":"Four aces in 52 cards gives 4/52, which simplifies to 1/13."},{"id":"q8","question":"What is the probability of an event that can never happen?","options":[{"id":"a","text":"1/2","is_correct":false},{"id":"b","text":"1","is_correct":false},{"id":"c","text":"0","is_correct":true},{"id":"d","text":"-1","is_correct":false}],"explanation":"Probability runs from 0 (impossible) to 1 (certain)."}]'::jsonb,
  null,
  array['math', 'trivia', 'probability', 'statistics', 'chance']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-probabilidad',
  'Trivia de probabilidad: azar, dados y paradojas',
  'Ocho preguntas sobre monedas, dados, cartas y los resultados contraintuitivos que hacen tan sorprendente a la probabilidad.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"¿Cuál es la probabilidad de que salga cara al lanzar una moneda justa?","options":[{"id":"a","text":"1/4","is_correct":false},{"id":"b","text":"1/2","is_correct":true},{"id":"c","text":"1/3","is_correct":false},{"id":"d","text":"1","is_correct":false}],"explanation":"Una moneda justa tiene dos resultados igual de probables, así que cada uno tiene 1/2 o 50 %."},{"id":"q2","question":"Al lanzar un dado justo de seis caras, ¿cuál es la probabilidad de sacar un 6?","options":[{"id":"a","text":"1/3","is_correct":false},{"id":"b","text":"1/2","is_correct":false},{"id":"c","text":"1/6","is_correct":true},{"id":"d","text":"1/12","is_correct":false}],"explanation":"Una cara favorable entre seis da 1/6, cerca del 16,7 %."},{"id":"q3","question":"Al lanzar dos dados, ¿qué suma es la más probable?","options":[{"id":"a","text":"2","is_correct":false},{"id":"b","text":"6","is_correct":false},{"id":"c","text":"12","is_correct":false},{"id":"d","text":"7","is_correct":true}],"explanation":"El 7 se puede formar de seis maneras (1-6, 2-5, 3-4, 4-3, 5-2, 6-1), más que cualquier otra suma."},{"id":"q4","question":"En la famosa paradoja del cumpleaños, ¿cuántas personas hacen falta en una sala para que la probabilidad de que dos cumplan el mismo día supere el 50 %?","options":[{"id":"a","text":"23","is_correct":true},{"id":"b","text":"50","is_correct":false},{"id":"c","text":"100","is_correct":false},{"id":"d","text":"183","is_correct":false}],"explanation":"Con solo 23 personas la probabilidad de un cumpleaños compartido ya supera el 50 %."},{"id":"q5","question":"En el problema de Monty Hall, después de que el presentador revela una cabra, cambiar de puerta deja tu probabilidad de ganar en...","options":[{"id":"a","text":"1/3, igual que antes","is_correct":false},{"id":"b","text":"2/3, el doble de la original","is_correct":true},{"id":"c","text":"1/2, como lanzar una moneda","is_correct":false},{"id":"d","text":"1/4, menos que antes","is_correct":false}],"explanation":"Tu primera elección tenía 1/3; la otra puerta cerrada conserva el 2/3 restante."},{"id":"q6","question":"¿Cuál es la probabilidad de sacar cara dos veces seguidas con una moneda justa?","options":[{"id":"a","text":"1/2","is_correct":false},{"id":"b","text":"1/3","is_correct":false},{"id":"c","text":"1/8","is_correct":false},{"id":"d","text":"1/4","is_correct":true}],"explanation":"Los eventos independientes se multiplican: 1/2 × 1/2 = 1/4."},{"id":"q7","question":"Al sacar una carta de una baraja estándar de 52 cartas, ¿cuál es la probabilidad de que sea un as?","options":[{"id":"a","text":"1/13","is_correct":true},{"id":"b","text":"1/26","is_correct":false},{"id":"c","text":"1/4","is_correct":false},{"id":"d","text":"1/52","is_correct":false}],"explanation":"Cuatro ases entre 52 cartas dan 4/52, que se simplifica a 1/13."},{"id":"q8","question":"¿Cuál es la probabilidad de un evento que nunca puede ocurrir?","options":[{"id":"a","text":"1/2","is_correct":false},{"id":"b","text":"1","is_correct":false},{"id":"c","text":"0","is_correct":true},{"id":"d","text":"-1","is_correct":false}],"explanation":"La probabilidad va de 0 (imposible) a 1 (seguro)."}]'::jsonb,
  null,
  array['matemáticas', 'trivia', 'probabilidad', 'estadística', 'azar']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-math-in-everyday-life-trivia',
  'Math in Everyday Life Trivia: Numbers You Use',
  'Eight questions on tips, discounts, unit conversions, recipes and the arithmetic behind daily decisions.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"An item costs $80 and is on sale for 25% off. How much do you pay?","options":[{"id":"a","text":"$55","is_correct":false},{"id":"b","text":"$60","is_correct":true},{"id":"c","text":"$65","is_correct":false},{"id":"d","text":"$70","is_correct":false}],"explanation":"25% of $80 is $20, so you pay $80 − $20 = $60."},{"id":"q2","question":"To leave a 20% tip on a $45 bill, the tip should be...","options":[{"id":"a","text":"$7","is_correct":false},{"id":"b","text":"$8","is_correct":false},{"id":"c","text":"$9","is_correct":true},{"id":"d","text":"$10","is_correct":false}],"explanation":"10% of $45 is $4.50, so 20% is double: $9."},{"id":"q3","question":"A recipe for 4 people calls for 2 cups of flour. How much flour do you need for 6 people?","options":[{"id":"a","text":"2.5 cups","is_correct":false},{"id":"b","text":"3 cups","is_correct":true},{"id":"c","text":"3.5 cups","is_correct":false},{"id":"d","text":"4 cups","is_correct":false}],"explanation":"Scaling by 6/4 = 1.5 turns 2 cups into 3 cups."},{"id":"q4","question":"Driving at 60 miles per hour for 90 minutes, how far do you travel?","options":[{"id":"a","text":"60 miles","is_correct":false},{"id":"b","text":"80 miles","is_correct":false},{"id":"c","text":"90 miles","is_correct":true},{"id":"d","text":"120 miles","is_correct":false}],"explanation":"90 minutes is 1.5 hours, and 60 × 1.5 = 90 miles."},{"id":"q5","question":"A pizza is cut into 8 equal slices. What fraction of the pizza is one slice?","options":[{"id":"a","text":"1/6","is_correct":false},{"id":"b","text":"1/8","is_correct":true},{"id":"c","text":"1/10","is_correct":false},{"id":"d","text":"1/12","is_correct":false}],"explanation":"Eight equal parts means each slice is 1/8, or 12.5%."},{"id":"q6","question":"Which formula converts degrees Celsius to Fahrenheit?","options":[{"id":"a","text":"F = C × 5/9 + 32","is_correct":false},{"id":"b","text":"F = C + 32","is_correct":false},{"id":"c","text":"F = C × 9/5 + 32","is_correct":true},{"id":"d","text":"F = C × 2 + 30","is_correct":false}],"explanation":"Check it: 0 °C becomes 0 × 9/5 + 32 = 32 °F, the freezing point of water."},{"id":"q7","question":"Three friends split a $90 bill evenly. How much does each pay?","options":[{"id":"a","text":"$25","is_correct":false},{"id":"b","text":"$27","is_correct":false},{"id":"c","text":"$30","is_correct":true},{"id":"d","text":"$33","is_correct":false}],"explanation":"$90 ÷ 3 = $30 per person."},{"id":"q8","question":"You spend $2.50 on coffee every workday. How much do you spend in a 5-day week?","options":[{"id":"a","text":"$10.00","is_correct":false},{"id":"b","text":"$12.50","is_correct":true},{"id":"c","text":"$15.00","is_correct":false},{"id":"d","text":"$17.50","is_correct":false}],"explanation":"$2.50 × 5 = $12.50 per week."}]'::jsonb,
  null,
  array['math', 'trivia', 'everyday math', 'arithmetic', 'money']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-matematicas-en-la-vida-diaria',
  'Trivia de matemáticas en la vida diaria: números de cada día',
  'Ocho preguntas sobre propinas, descuentos, conversiones, recetas y la aritmética detrás de las decisiones de cada día.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'science'),
  '[{"id":"q1","question":"Un artículo cuesta 80 dólares y tiene un 25 % de descuento. ¿Cuánto pagas?","options":[{"id":"a","text":"55 dólares","is_correct":false},{"id":"b","text":"60 dólares","is_correct":true},{"id":"c","text":"65 dólares","is_correct":false},{"id":"d","text":"70 dólares","is_correct":false}],"explanation":"El 25 % de 80 son 20 dólares, así que pagas 80 − 20 = 60."},{"id":"q2","question":"Para dejar una propina del 20 % en una cuenta de 45 dólares, la propina debe ser...","options":[{"id":"a","text":"7 dólares","is_correct":false},{"id":"b","text":"8 dólares","is_correct":false},{"id":"c","text":"9 dólares","is_correct":true},{"id":"d","text":"10 dólares","is_correct":false}],"explanation":"El 10 % de 45 son 4,50 dólares, así que el 20 % es el doble: 9."},{"id":"q3","question":"Una receta para 4 personas lleva 2 tazas de harina. ¿Cuánta harina necesitas para 6 personas?","options":[{"id":"a","text":"2,5 tazas","is_correct":false},{"id":"b","text":"3 tazas","is_correct":true},{"id":"c","text":"3,5 tazas","is_correct":false},{"id":"d","text":"4 tazas","is_correct":false}],"explanation":"Al escalar por 6/4 = 1,5, las 2 tazas se convierten en 3."},{"id":"q4","question":"Viajando a 60 km/h durante 90 minutos, ¿qué distancia recorres?","options":[{"id":"a","text":"60 km","is_correct":false},{"id":"b","text":"80 km","is_correct":false},{"id":"c","text":"90 km","is_correct":true},{"id":"d","text":"120 km","is_correct":false}],"explanation":"90 minutos son 1,5 horas, y 60 × 1,5 = 90 km."},{"id":"q5","question":"Una pizza se corta en 8 porciones iguales. ¿Qué fracción de la pizza es una porción?","options":[{"id":"a","text":"1/6","is_correct":false},{"id":"b","text":"1/8","is_correct":true},{"id":"c","text":"1/10","is_correct":false},{"id":"d","text":"1/12","is_correct":false}],"explanation":"Ocho partes iguales significan que cada porción es 1/8, es decir, el 12,5 %."},{"id":"q6","question":"¿Qué fórmula convierte grados Celsius a Fahrenheit?","options":[{"id":"a","text":"F = C × 5/9 + 32","is_correct":false},{"id":"b","text":"F = C + 32","is_correct":false},{"id":"c","text":"F = C × 9/5 + 32","is_correct":true},{"id":"d","text":"F = C × 2 + 30","is_correct":false}],"explanation":"Comprobación: 0 °C se convierte en 0 × 9/5 + 32 = 32 °F, el punto de congelación del agua."},{"id":"q7","question":"Tres amigos dividen una cuenta de 90 dólares en partes iguales. ¿Cuánto paga cada uno?","options":[{"id":"a","text":"25 dólares","is_correct":false},{"id":"b","text":"27 dólares","is_correct":false},{"id":"c","text":"30 dólares","is_correct":true},{"id":"d","text":"33 dólares","is_correct":false}],"explanation":"90 ÷ 3 = 30 dólares por persona."},{"id":"q8","question":"Si gastas 2,50 dólares en café cada día laboral, ¿cuánto gastas en una semana de 5 días?","options":[{"id":"a","text":"10 dólares","is_correct":false},{"id":"b","text":"12,50 dólares","is_correct":true},{"id":"c","text":"15 dólares","is_correct":false},{"id":"d","text":"17,50 dólares","is_correct":false}],"explanation":"2,50 × 5 = 12,50 dólares por semana."}]'::jsonb,
  null,
  array['matemáticas', 'trivia', 'vida diaria', 'aritmética', 'dinero']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

-- categories.quiz_count is maintained by the trigger on quizzes.

